async function createRedeemCode(params) {
	const firestore = requireDb();
	const normalized = params.code.trim().toUpperCase();
	if (!/^[A-Z0-9_-]{4,40}$/.test(normalized)) throw new Error("Mã chỉ gồm chữ in hoa, số, dấu gạch ngang (4-40 ký tự).");
	const amount = Math.floor(params.amount);
	const maxUses = Math.floor(params.maxUses);
	if (amount < 1 || amount > 1e6) throw new Error("Mệnh giá Xu DOPI phải từ 1 đến 1.000.000.");
	if (maxUses < 1 || maxUses > 500) throw new Error("Số lượt dùng tối đa phải từ 1 đến 500.");
	const ref = doc(firestore, "redeem_codes", normalized);
	if ((await getDoc(ref)).exists()) throw new Error(`Mã "${normalized}" đã tồn tại trên hệ thống.`);
	const payload = {
		code: normalized,
		amount,
		maxUses,
		usedCount: 0,
		usedBy: [],
		expiresAt: params.expiresAt,
		createdBy: params.createdBy,
		createdAt: Date.now(),
		isActive: true
	};
	try {
		await setDoc(ref, sanitizeForFirestore(payload));
		return payload;
	} catch (error) {
		handleFirestoreError(error, OperationType.CREATE, `redeem_codes/${normalized}`);
	}
}
