function translateAuthError(codeOrMessage) {
	if (codeOrMessage.includes("auth/invalid-credential") || codeOrMessage.includes("auth/wrong-password")) return "Email hoặc mật khẩu chưa chính xác.";
	if (codeOrMessage.includes("auth/user-not-found")) return "Không tìm thấy tài khoản với email này.";
	if (codeOrMessage.includes("auth/email-already-in-use")) return "Email này đã được đăng ký tài khoản DOPI TOWNE.";
	if (codeOrMessage.includes("auth/weak-password")) return "Mật khẩu cần tối thiểu 6 ký tự.";
	if (codeOrMessage.includes("auth/popup-closed-by-user")) return "Bạn đã đóng cửa sổ đăng nhập Google.";
	if (codeOrMessage.includes("auth/operation-not-allowed")) return "Phương thức đăng nhập Email/Mật khẩu chưa được bật trong Firebase Console. Hãy đăng nhập bằng Google hoặc bật Email/Password trong Firebase Authentication.";
	if (codeOrMessage.includes("auth/unauthorized-domain")) return "Tên miền hiện tại chưa được thêm vào Authorized Domains trong Firebase Authentication.";
	return "Không thể đăng nhập lúc này. Vui lòng kiểm tra thông tin và thử lại.";
}
