function formatRemainingDuration(ms) {
	const totalSec = Math.max(0, Math.ceil(ms / 1e3));
	const h = Math.floor(totalSec / 3600);
	const m = Math.floor(totalSec % 3600 / 60);
	const s = totalSec % 60;
	if (h > 0) return `${h}g ${m}p`;
	if (m > 0) return `${m}p ${s}s`;
	return `${s}s`;
}
