	const handleDeliverNpcOrder = async (order) => {
		if (!userData) return;
		for (const [itemId, qty] of Object.entries(order.items)) if ((userData.inventory[itemId] || 0) < qty) {
			soundEngine.playError();
			pushToast("error", "Kho chưa đủ hàng để giao đơn này.");
			return;
		}
		const nextInv = { ...userData.inventory };
		for (const [itemId, qty] of Object.entries(order.items)) {
			const rem = (nextInv[itemId] || 0) - qty;
			if (rem <= 0) delete nextInv[itemId];
			else nextInv[itemId] = rem;
		}
		const bonuses = getBusinessBonuses(userData);
		const grossGold = Math.round(order.rewardGold * (1 + bonuses.orderRewardBonusPct / 100));
		const ipoListed = Boolean(myP2PCompany?.isListed);
		const ipoDividendCut = ipoListed ? Math.max(1, Math.floor(grossGold * (myP2PCompany?.dividendRate || 5) / 100)) : 0;
		const ownerNetGold = Math.max(1, grossGold - ipoDividendCut);
		const expRes = applyExpAndLevelUp(userData.level, userData.exp, order.rewardExp);
		const replacement = generateNpcOrders(expRes.level, Date.now(), Math.floor(Math.random() * 97), bonuses.orderRefreshReductionPct)[0];
		const nextUserSnapshot = {
			...userData,
			level: expRes.level,
			exp: expRes.exp,
			gold: userData.gold + ownerNetGold,
			eventTickets: (userData.eventTickets || 0) + 2,
			inventory: nextInv,
			npcOrders: userData.npcOrders.map((o) => o.id === order.id ? replacement : o),
			dailyQuests: userData.dailyQuests.map((q) => q.type === "order" ? {
				...q,
				progress: Math.min(q.target, q.progress + 1)
			} : q),
			stats: {
				...userData.stats,
				totalOrdersDone: (userData.stats?.totalOrdersDone || 0) + 1
			}
		};
		await commitUserUpdate(() => nextUserSnapshot);
		if (ipoListed && ipoDividendCut > 0) {
			if (isSandboxMode && myP2PCompany) {
				const updatedComp = buildP2PCompanyPayload(nextUserSnapshot, myP2PCompany.dividendRate, true, {
					...myP2PCompany,
					dividendPool: myP2PCompany.dividendPool + ipoDividendCut
				}, Date.now());
				setMyP2PCompany(updatedComp);
				setP2pCompanies((prev) => prev.map((c) => c.ownerUid === userData.uid ? updatedComp : c));
			} else if (!isSandboxMode) syncP2PCompanyDividendFromOrder(nextUserSnapshot, grossGold);
		}
		soundEngine.playOrder();
		pushToast("success", `Giao đơn cho ${order.customerName} thành công! +${formatNumber(ownerNetGold)} Vàng, +${order.rewardExp} EXP, +2 Vé Sự Kiện.${ipoDividendCut > 0 ? ` (Trích +${formatNumber(ipoDividendCut)}V vào Quỹ Cổ Tức IPO)` : ""}`);
	};
